/// Every setting, by its number in schema.json's SETTING.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum SettingKey {
    /// Ground color from the art pack (four taps of the layer array per
    /// fragment) instead of the flat per-instance average. The paint shader's
    /// `frame.low_spec` is this, inverted.
    ///
    /// Low because the four taps are all of it: fill rate, which scales with
    /// the screen and not with the world, and nothing else — no geometry, no
    /// pass of its own, and no work off the GPU past an atlas the client
    /// already holds.
    textures = 0,
    /// Procedurally scattered decor only; what the player placed stays.
    ///
    /// Med because it is models rather than a shading term: the GPU grows the
    /// ground's decor where the eye's windows are (decor_cs) and the frame draws
    /// each kind as a model, a sprite (an impostor) or nothing by the angle it
    /// spans, so what it costs follows what is in view. It has been the frame's
    /// own bottleneck — doc/minutes/archive/20260912-what-to-render-when.md reads
    /// GPU p95 24.1 ms with 2.26 M decor triangles and 15% of moving frames
    /// missing a vsync, before the tiers. The badge is an ordering, and this is
    /// the one to reach for before any shading term.
    decor = 1,
    /// The cumulus' models and the altocumulus and cirrus sheets
    /// (rust/client/kernel/src/domain/scene/environment/cloud.rs, rust/client/render/src/gpu/cloud.rs).
    /// Med as decor is: models in view, and a pass over the screen for the sheets.
    clouds = 2,
    /// The places' markers over the world, from the published places tiles.
    place = 3,
    /// Rotate-drag and pinch stop writing polar; azimuth is unaffected.
    /// Off by default: the tilt is the one control a view from above is expected to
    /// have, and locking it reads as the app being stuck.
    tilt_lock = 4,
    /// Which controller makes the camera's pose; CAMERA_MODES says each. To
    /// first person the person stands at the pivot, the eye at its
    /// height over the ground; to third the pivot is laid on the ground
    /// and the eye steps back by the radius.
    camera_mode = 5,
    /// The pivot stands on what supports it and a pan takes the lowest way over what is in it (navigation/support.rs). Off, a pan keeps the pivot's height and passes through anything; a tap still stands it on the surface it struck.
    surface_follow = 6,
    /// What the camera does when the controls would put it underground; ORBIT_OBSTACLE_MODES says each. Only `climb` goes into a tunnel (orbit/terrain_gate.rs `dive`), so a shipped build holds it, and the others are a development build's to compare, each session from the default.
    orbit_obstacle = 7,
    /// Darkens cube edges that border open air (rust/client/render/src/frame/shader/paint.wgsl).
    /// A few fragment ops behind a uniform; the shader is the same either way.
    edge_shade = 8,
    /// A uniform on an already-compiled shader term; not a pass.
    rim_light = 9,
    /// corner, the occlusion a voxel world reads off its own cubes' faces;
    /// screen, N8AO's screen-space pass, the costliest of the three. AO_MODES
    /// says each.
    ao = 10,
    /// The sun's shadow map (rust/client/render/src/gpu/shadow.rs): the world
    /// cast once more from the sun as the eye's rays are, beams and samples on
    /// the observed pyramid, the boxes they stop at drawn and a texel's pick
    /// taken, the rest walked (pxl-shader sun.rs), recast only where what it
    /// reads moves; decor and the actors drawn into it depth only, and a 3x3
    /// compare per fragment; 16 MB of map.
    shadows = 11,
    /// The pixels the world is filled at, the GPU's largest cost: two to a
    /// CSS pixel is four times the fragments of one. RES_MODES says each.
    res = 12,
    /// Where the camera and the pointer are, read live (profiler/read.rs, NOW's view section).
    view = 13,
    /// The profiler's panel, with the profiler recording while it is on (profiler/window.rs `profiler_follow`).
    profiler = 14,
    /// Marks for the pivot and the cell it floors to, and rings in the level, the view's upright and the north–south planes (domain/scene/indicator/frame_gizmo.rs); and over the ground the eye's windows' bricks by how they stand, their tiles and shards (domain/scene/indicator/coverage_gizmo.rs).
    world_gizmo = 15,
    /// The camera grid over the screen, rings a cell apart about the optical axis cut into cells of one solid angle each, and the cells the rays stop on tinted by the share of a grid cell a face shows the eye: green within one to four, blue finer, red coarser (domain/scene/indicator/camera_gizmo.rs).
    camera_gizmo = 16,
    person = 17,
    pet = 18,
    /// Each ray's pixel coloured by the nodes asked of the world on its way from the eye, as the frame casts it, on one fixed log ramp up to 1024: the beam ray's walk its cell starts off (beam::LINE_VISITS) and its own after, or, where it took a sample's block or the samples' sky, that sample's, counted the same way (beam::SAMPLE_VISITS; rust/client/render/src/frame/shader/screen_ray.wgsl).
    ray_steps = 19,
    /// How the sun's shadow map is cast — the slots that took the raster's pick and the boxes it drew — counted on the GPU and summed since boot into the profiler's sun lanes (rust/client/render/src/gpu/ray/tally.rs, rust/client/shader/src/sun.rs). The counting's atomics run in the sun's spans, so time them with it off.
    sun_counts = 20,
}

impl SettingKey {
    pub const ALL: [SettingKey; 21] = [
        SettingKey::textures,
        SettingKey::decor,
        SettingKey::clouds,
        SettingKey::place,
        SettingKey::tilt_lock,
        SettingKey::camera_mode,
        SettingKey::surface_follow,
        SettingKey::orbit_obstacle,
        SettingKey::edge_shade,
        SettingKey::rim_light,
        SettingKey::ao,
        SettingKey::shadows,
        SettingKey::res,
        SettingKey::view,
        SettingKey::profiler,
        SettingKey::world_gizmo,
        SettingKey::camera_gizmo,
        SettingKey::person,
        SettingKey::pet,
        SettingKey::ray_steps,
        SettingKey::sun_counts,
    ];

    /// One past the highest number: the length of a list of every
    /// setting's value at its number, where a number not given out stays 0.
    pub const SLOTS: usize = 21;

    /// The setting a number names, or none for a number the table does not give out.
    pub fn of(number: u32) -> Option<SettingKey> {
        SettingKey::ALL
            .into_iter()
            .find(|key| *key as u32 == number)
    }

    pub fn kind(self) -> SettingKind {
        match self {
            SettingKey::textures => SettingKind::Toggle,
            SettingKey::decor => SettingKind::Toggle,
            SettingKey::clouds => SettingKind::Toggle,
            SettingKey::place => SettingKind::Toggle,
            SettingKey::tilt_lock => SettingKind::Toggle,
            SettingKey::camera_mode => SettingKind::Choice,
            SettingKey::surface_follow => SettingKind::Toggle,
            SettingKey::orbit_obstacle => SettingKind::Choice,
            SettingKey::edge_shade => SettingKind::Toggle,
            SettingKey::rim_light => SettingKind::Toggle,
            SettingKey::ao => SettingKind::Choice,
            SettingKey::shadows => SettingKind::Toggle,
            SettingKey::res => SettingKind::Choice,
            SettingKey::view => SettingKind::Toggle,
            SettingKey::profiler => SettingKind::Toggle,
            SettingKey::world_gizmo => SettingKind::Toggle,
            SettingKey::camera_gizmo => SettingKind::Toggle,
            SettingKey::person => SettingKind::Index,
            SettingKey::pet => SettingKind::Index,
            SettingKey::ray_steps => SettingKind::Toggle,
            SettingKey::sun_counts => SettingKind::Toggle,
        }
    }

    /// Written to the settings' kept slot and read from it; one schema.json
    /// marks `kept` false is held for the session alone.
    pub fn is_kept(self) -> bool {
        !matches!(
            self,
            SettingKey::place
                | SettingKey::camera_mode
                | SettingKey::orbit_obstacle
                | SettingKey::sky_time
        )
    }

    /// Offered by a development build only.
    pub fn dev(self) -> bool {
        matches!(
            self,
            SettingKey::surface_follow | SettingKey::ray_steps | SettingKey::sun_counts
        )
    }

    /// A choice's option a development build only offers.
    pub fn dev_option(self, _value: u32) -> bool {
        false
    }
}

/// Every setting's value: what the store holds, and what the app reads.
#[derive(Clone, Debug, PartialEq)]
pub struct Settings {
    pub textures: bool,
    pub decor: bool,
    pub clouds: bool,
    pub place: bool,
    pub tilt_lock: bool,
    pub camera_mode: CameraMode,
    pub surface_follow: bool,
    pub orbit_obstacle: OrbitObstacleMode,
    pub edge_shade: bool,
    pub rim_light: bool,
    pub ao: AoMode,
    pub shadows: bool,
    pub res: ResMode,
    pub view: bool,
    pub profiler: bool,
    pub world_gizmo: bool,
    pub camera_gizmo: bool,
    pub person: u8,
    pub pet: u8,
    pub ray_steps: bool,
    pub sun_counts: bool,
}

impl Settings {
    /// Every setting at schema.json's default.
    pub const DEFAULT: Settings = Settings {
        textures: true,
        decor: true,
        clouds: true,
        place: false,
        tilt_lock: false,
        camera_mode: CameraMode::orbit,
        surface_follow: true,
        orbit_obstacle: OrbitObstacleMode::climb,
        edge_shade: true,
        rim_light: true,
        ao: AoMode::corner,
        shadows: false,
        res: ResMode::auto,
        view: false,
        profiler: false,
        world_gizmo: false,
        camera_gizmo: false,
        person: 1,
        pet: 5,
        ray_steps: false,
        sun_counts: false,
    };

    /// A setting's value as it crosses and is kept: a toggle's 0 or 1, a
    /// choice's option by its number, an index as itself.
    pub fn get(&self, key: SettingKey) -> u32 {
        match key {
            SettingKey::textures => self.textures as u32,
            SettingKey::decor => self.decor as u32,
            SettingKey::clouds => self.clouds as u32,
            SettingKey::place => self.place as u32,
            SettingKey::tilt_lock => self.tilt_lock as u32,
            SettingKey::camera_mode => self.camera_mode as u32,
            SettingKey::surface_follow => self.surface_follow as u32,
            SettingKey::orbit_obstacle => self.orbit_obstacle as u32,
            SettingKey::edge_shade => self.edge_shade as u32,
            SettingKey::rim_light => self.rim_light as u32,
            SettingKey::ao => self.ao as u32,
            SettingKey::shadows => self.shadows as u32,
            SettingKey::res => self.res as u32,
            SettingKey::view => self.view as u32,
            SettingKey::profiler => self.profiler as u32,
            SettingKey::world_gizmo => self.world_gizmo as u32,
            SettingKey::camera_gizmo => self.camera_gizmo as u32,
            SettingKey::person => self.person as u32,
            SettingKey::pet => self.pet as u32,
            SettingKey::ray_steps => self.ray_steps as u32,
            SettingKey::sun_counts => self.sun_counts as u32,
        }
    }

    /// Sets a setting from its value as it crosses; false, and nothing set,
    /// for a value the setting cannot hold.
    pub fn set(&mut self, key: SettingKey, val: u32) -> bool {
        match key {
            SettingKey::textures if val <= 1 => self.textures = val == 1,
            SettingKey::decor if val <= 1 => self.decor = val == 1,
            SettingKey::clouds if val <= 1 => self.clouds = val == 1,
            SettingKey::place if val <= 1 => self.place = val == 1,
            SettingKey::tilt_lock if val <= 1 => self.tilt_lock = val == 1,
            SettingKey::camera_mode => match CameraMode::of(val) {
                Some(o) => self.camera_mode = o,
                None => return false,
            },
            SettingKey::surface_follow if val <= 1 => self.surface_follow = val == 1,
            SettingKey::orbit_obstacle => match OrbitObstacleMode::of(val) {
                Some(o) => self.orbit_obstacle = o,
                None => return false,
            },
            SettingKey::edge_shade if val <= 1 => self.edge_shade = val == 1,
            SettingKey::rim_light if val <= 1 => self.rim_light = val == 1,
            SettingKey::ao => match AoMode::of(val) {
                Some(o) => self.ao = o,
                None => return false,
            },
            SettingKey::shadows if val <= 1 => self.shadows = val == 1,
            SettingKey::res => match ResMode::of(val) {
                Some(o) => self.res = o,
                None => return false,
            },
            SettingKey::view if val <= 1 => self.view = val == 1,
            SettingKey::profiler if val <= 1 => self.profiler = val == 1,
            SettingKey::world_gizmo if val <= 1 => self.world_gizmo = val == 1,
            SettingKey::camera_gizmo if val <= 1 => self.camera_gizmo = val == 1,
            SettingKey::person => match u8::try_from(val) {
                Ok(n) => self.person = n,
                Err(_) => return false,
            },
            SettingKey::pet => match u8::try_from(val) {
                Ok(n) => self.pet = n,
                Err(_) => return false,
            },
            SettingKey::ray_steps if value <= 1 => self.ray_steps = value == 1,
            SettingKey::sun_counts if value <= 1 => self.sun_counts = value == 1,
            _ => return false,
        }
        true
    }
}
